"""Contractors & Construction toolkit (kit id: construction). Text for the web pages and the "How to use" sheets.
   Files: Construction-Estimate-BOQ.xlsx, Construction-RA-Bill-and-MB.xlsx, Construction-Labour-Wage-Register.xlsx,
   Construction-Material-Register.xlsx, Construction-Daily-Site-Diary.docx, Construction-Work-Order-Draft.docx; online tool contractor-estimate."""

KITS = [
    dict(id='construction', name='Contractors & Construction', icon='🏗️', color='#EA580C',
         title='Contractors & Construction Toolkit: Estimate, BOQ, RA Bill and Site Registers',
         desc='Free construction templates: estimate and BOQ with abstract of cost, RA bill with measurement book, labour wage register, material register, site diary and work order.',
         intro=['A building contractor runs two businesses at once: the site, where labour, material and work have to be counted every day, and the office, where those counts become estimates, running bills and payments. When the site records are loose sheets of paper, the bills are late, quantities are argued over and nobody knows how much cement really went into the slab.',
                'This toolkit gives contractors, builders and site engineers the core paperwork as ready Excel and Word files: an estimate with bill of quantities (BOQ) and abstract of cost, a running account (RA) bill that reads quantities from a measurement book, a labour attendance and wage register, a material inward and issue register, a daily site diary and a work order starting draft. An online estimate maker turns a BOQ into a printable quotation in minutes.'],
         who='Civil and interior contractors, builders, sub-contractors and petty contractors, site engineers and supervisors, quantity surveyors, and owners building their own house.'),
]

ITEMS = [
    dict(id='con-estimate-boq-excel', kit='construction', kind='excel', icon='📐', name='Construction Estimate & BOQ (Excel)',
         title='Construction Estimate & BOQ in Excel: Measurement Sheet and Abstract of Cost',
         desc='Free Excel estimate and bill of quantities: measurement sheet (Nos × L × B × D), BOQ with rates, section-wise abstract of cost, contingency, GST and cost per sq ft.',
         files=[('Construction-Estimate-BOQ.xlsx', 'Estimate and BOQ workbook')],
         preview={'Construction-Estimate-BOQ.xlsx': ('Abstract', 'A1:D37')},
         lead='Prepare a detailed estimate the way engineers are taught to: take off the measurements (number × length × breadth × depth), carry the quantity to the bill of quantities, apply your rates and let the abstract of cost add everything up by section. The workbook adds overheads, contingency and GST, writes the total in words and shows the cost per square foot, so a client can compare it with other quotes.',
         inside=['Project sheet: name of work, client, site, estimate number, built-up area, overheads %, contingency %, GST % and your own list of sections (earthwork, concrete, steel, masonry and more)',
                 'Measurements sheet with 500 rows: item number, location, Nos, length, breadth and depth or height; quantity calculates itself and negative Nos deduct openings',
                 'BOQ sheet with 200 items: section, description, unit, quantity (typed or taken from the measurements), rate and amount',
                 'Abstract of cost: amount and share of each section, overheads, contingency, GST, grand total, amount in words and cost per sq ft',
                 'Sample estimate of a 1,200 sq ft ground-floor house to show how the sheets connect'],
         steps=['Open the Project sheet and type the name of work, client, site, estimate number and the built-up area. Set the overheads, contingency and GST percentages you want to show.',
                'Check the list of sections on the right of the Project sheet. Rename or add sections to match the way you group your work.',
                'On the BOQ sheet replace the sample items with your own: item number, section, full description, unit and rate.',
                'For items you measure from drawings, write each measurement on the Measurements sheet under the same item number: Nos, length, breadth and depth or height (leave a dimension empty if it does not apply). For openings and deductions type the Nos as a negative number.',
                'Leave the "Qty (typed)" column of the BOQ empty for those items: the quantity comes from the Measurements sheet. For lump-sum or counted items, simply type the quantity.',
                'Open the Abstract sheet to see the cost by section, the grand total, the amount in words and the cost per sq ft. Print the Abstract and the BOQ, or save them as PDF for the client.'],
         tips=['Write the BOQ description the way you would want it read in a dispute: material, mix or grade, thickness, and what is included (for example "including curing and shuttering").',
               'Keep units consistent between the measurements and the rate: cum for concrete and excavation, sqm for plaster and flooring, kg or MT for steel.',
               'Rates change quickly for cement and steel. Write the month of the rates on the Project sheet so an old estimate is not used by mistake.',
               'Contingency is for genuine unknowns (rock in excavation, small design changes). It is not a place to hide profit; show overheads and profit separately if your rates do not include them.'],
         faqs=[('What is the difference between an estimate, a BOQ and an abstract of cost?', 'The detailed estimate is the full working: measurements, quantities and rates. The bill of quantities (BOQ) lists each item of work with its unit, quantity, rate and amount. The abstract of cost summarises the BOQ by section and adds overheads, contingency and taxes to reach the total.'),
               ('How does the measurement sheet calculate quantity?', 'It multiplies the numbers you type in Nos, Length, Breadth and Depth or Height, ignoring empty cells. So 12 footings of 1.5 × 1.5 × 1.5 m give 40.5 cum, and a wall area needs only Nos, Length and Height. A negative Nos subtracts the quantity, which is how door and window openings are deducted.'),
               ('Which GST rate applies to construction work?', 'It depends on the kind of contract and the client: works contracts, affordable housing, government work and pure labour contracts can have different rates. The workbook lets you pick 0, 5, 12 or 18 percent; confirm the correct rate with your tax adviser before quoting.'),
               ('Can I use it for interior or renovation work?', 'Yes. Replace the sections with your own (false ceiling, modular kitchen, electrical, painting) and use units such as sqft, rft or nos. The formulas do not depend on the section names.')]),

    dict(id='con-estimate-maker', kit='construction', kind='online', tool='contractor-estimate', icon='⚡', name='Online Contractor Estimate & Quotation Maker',
         title='Online Construction Estimate Maker: Contractor Quotation with BOQ Lines',
         desc='Make a contractor estimate or quotation online: BOQ lines with unit, quantity (type 2×4.5×0.23), rate, section totals, contingency and GST. Print or download Excel and Word.',
         lead='Turn a list of work items into a clean estimate or quotation for your client. Type each item with its unit, quantity and rate; the quantity box accepts a measurement such as 2×4.5×0.23 or 10+12.5 and works it out. Items are grouped by section with section totals, then contingency and GST are added and the total is written in words. Print it, save it as PDF, or download it as Excel or Word. Your firm\'s details stay saved on this device.',
         inside=['Your firm\'s name, address, phone, GSTIN and registration number (saved on this device)', 'Estimate or quotation, number, date, valid-until date, client, site and name of work',
                 'BOQ lines with section, item description, unit, quantity and rate; quantities can be typed as measurements (Nos × L × B × D, or sums)',
                 'Section-wise totals, contingency %, GST % and round off, with the amount in words', 'Payment terms and exclusions printed below the BOQ',
                 'Print / Save as PDF, download as .xlsx and .docx; works offline once the site is installed as an app'],
         steps=['Type your firm\'s name, address, phone and GSTIN once. They stay saved in this browser.',
                'Choose Estimate or Quotation, then type the number, date, client name, site address and the name of work.',
                'Add the BOQ lines: pick a section, describe the item, choose the unit and type the quantity and rate. For a measured quantity type it as a calculation, for example 12×1.5×1.5×1.5.',
                'Set contingency and GST if you want them on the quote, and edit the payment terms and exclusions.',
                'Check the preview, then press Print / PDF, or download the Excel or Word file to edit further.'],
         tips=['Write in the exclusions what the client must arrange (water, electricity, approvals, materials they supply). Most site disputes start with something nobody wrote down.',
               'Use Quotation for a firm offer with a validity date and Estimate for a budget figure before the drawings are final.',
               'For a full measurement take-off with hundreds of lines, use the Construction Estimate & BOQ workbook in this toolkit and paste the totals here.'],
         faqs=[('How do I type a quantity as a measurement?', 'Use × or x or * between dimensions and + between parts: "2×4.5×0.23 + 1×3×0.23" gives 2.76. A minus sign deducts a part, for example "40 - 2×1.2×1.5" for a wall area less two windows. The preview shows the worked-out quantity.'),
               ('Is my estimate uploaded anywhere?', 'No. Everything is worked out inside your browser. Your firm details and the last draft are kept only in this browser on this device.'),
               ('Can I leave out GST?', 'Yes. Set GST to 0 and no tax line is shown. If you are registered, check the correct GST rate for the type of work with your tax adviser.'),
               ('Can I show item rates without a total, as a rate quotation?', 'Not in this version. Download the Word file and delete the totals if you want to send rates only.')]),

    dict(id='con-ra-bill-excel', kit='construction', kind='excel', icon='🧾', name='RA Bill & Measurement Book (Excel)',
         title='RA Bill Format in Excel: Running Account Bill with Measurement Book',
         desc='Free Excel running account (RA) bill: measurement book entries per bill, previous, this bill and up-to-date quantities, GST, retention, TDS and net payable in words.',
         files=[('Construction-RA-Bill-and-MB.xlsx', 'RA bill and measurement book workbook')],
         preview={'Construction-RA-Bill-and-MB.xlsx': ('Bill summary', 'A1:B28')},
         lead='Record every measurement once, in a measurement book with the bill number it belongs to, and the running account bill builds itself. For each item it shows the quantity up to the previous bill, in this bill and up to date, values them at the agreement rate, flags any item that has gone beyond the agreement quantity, and then works out GST, retention money, TDS and the other deductions to reach the net amount payable.',
         inside=['Contract sheet: name of work, employer, contractor, agreement number, current bill number and dates, and the deduction rates (retention, income-tax TDS, GST TDS, labour cess) with advance recovery and other deductions',
                 'Items sheet: agreement items with unit, quantity, rate and amount; contract value totals itself',
                 'MB (measurement book) sheet with 1,000 rows: date, bill number, item, location, Nos × L × B × D and who measured it',
                 'Bill items sheet: previous, this bill and up-to-date quantities and amounts for every item, with an "excess" warning beyond the agreement quantity',
                 'Bill summary: value of work done, GST, retention, TDS, cess, recoveries, net payable in words, retention held to date and signature lines'],
         steps=['On the Contract sheet type the name of work, the employer, the contractor and the agreement details. Check each deduction rate against your agreement and change it if needed.',
                'On the Items sheet list the agreement items exactly as in the work order: item number, description, unit, agreement quantity and rate.',
                'Each time work is measured, add rows on the MB sheet: date, the bill number the measurement belongs to, the item number, the location and the dimensions. The quantity calculates itself.',
                'When a bill is due, type its number on the Contract sheet (Bill No. for this bill). Measurements with a lower bill number count as "previous", those with this number as "this bill".',
                'Open Bill items to check quantities. Any item shown as Excess has gone beyond the agreement quantity and needs an extra item or variation approval.',
                'Open Bill summary for the net amount payable, print both bill sheets, and get them signed by the contractor, the site engineer and the person approving payment.'],
         tips=['Never edit old measurement rows after a bill is paid. If something was measured wrongly, add a correcting row with a negative Nos in the next bill, so the history stays visible.',
               'Ask the client\'s engineer to initial the printed MB pages at each measurement; it saves arguments at the final bill.',
               'Retention is usually released after the defects liability period. Keep the "retention held to date" figure from the last bill to claim it.',
               'TDS and cess rules depend on the contractor\'s status and the client (for example individual or company, government or private). Check the current rates with your accountant.'],
         faqs=[('What is an RA bill?', 'A running account (RA) bill is a part payment for the work done so far in a long contract. Each RA bill shows the work done up to date, subtracts what was already billed, and pays the difference after deductions. The final bill closes the account.'),
               ('How does the bill know which measurements are previous?', 'Every row in the measurement book carries a bill number. Rows with a bill number lower than the current bill are counted as "up to previous bill", rows with the current number as "this bill".'),
               ('Why is GST added before retention and TDS?', 'GST is charged on the value of work billed, then the employer makes its deductions from the bill. In this sheet retention, TDS and cess are worked out on the value of work excluding GST, which is the usual practice; change the rates to zero for any deduction that does not apply to your contract.'),
               ('Can I bill extra items not in the agreement?', 'Add them on the Items sheet with a new item number (for example EX-1) and an agreement quantity of 0 once they are approved. They will show as Excess until the approved quantity is entered.')]),

    dict(id='con-labour-wage-excel', kit='construction', kind='excel', icon='👷', name='Labour Attendance & Wage Register (Excel)',
         title='Labour Attendance and Wage Register for Construction Sites in Excel',
         desc='Free Excel labour register for sites: workers by trade, daily P/A/H attendance for a week or month, overtime, advances, net wages and daily headcount by date.',
         files=[('Construction-Labour-Wage-Register.xlsx', 'Labour attendance and wage register')],
         preview={'Construction-Labour-Wage-Register.xlsx': ('Wages', 'A1:K12')},
         lead='Mark daily attendance for every worker on site, add overtime hours and advances, and the register works out each worker\'s wages for the week, fortnight or month: days worked, wages at the daily rate, overtime, advance recovered and the net amount to pay. A headcount row shows how many people were on site each day, which is what clients and safety officers ask for first.',
         inside=['Settings: site, contractor, wage period start date and length (7 days for weekly payment, 14 or up to 31), hours in a working day and overtime rate',
                 'Workers sheet for 100 workers: code, name, trade (mason, helper, carpenter, bar bender and more), daily wage, phone and bank or UPI',
                 'Attendance grid with dates and weekdays filled in from the period: P present, H half day, A absent; totals per worker and headcount per day',
                 'Advances sheet: date, worker and amount; only advances inside the wage period are deducted',
                 'Wages sheet: days worked, wages, overtime amount, gross, advance deducted, net payable and a signature column, with period totals'],
         steps=['On the Settings sheet type the site name, the contractor, the first day of the wage period and how many days it has (7 for weekly wages).',
                'On the Workers sheet list every worker with a short code, name, trade and agreed daily wage.',
                'Each day mark P, H or A against each worker on the Attendance sheet. Type the overtime hours for the period in the OT hours column.',
                'Whenever a worker takes an advance, add a row on the Advances sheet with the date, the worker code and the amount.',
                'On wage day open the Wages sheet: it shows the net amount for each worker. Print it, pay, and take each worker\'s signature or thumb impression.',
                'For the next period save a copy of the file, change the start date on the Settings sheet and clear the attendance marks. Keep the worker list.'],
         tips=['Daily wages must not be lower than the minimum wage notified for that trade in your state; check the current rates, which are revised from time to time.',
               'Paying wages through bank or UPI and keeping this register gives a clear record if a labour inspector or the client asks.',
               'Overtime here is paid at the rate you set on the Settings sheet (twice the ordinary hourly rate to start with, which many labour laws ask for). Change it if your agreement says otherwise.',
               'Use the headcount row for the daily site diary and for planning: a sudden drop in helpers usually explains why progress slowed.'],
         faqs=[('How are days worked calculated?', 'Each P counts as one day and each H as half a day. Wages are days worked multiplied by the daily wage.'),
               ('How is overtime worked out?', 'Overtime hours × (daily wage ÷ hours in a working day) × the overtime rate. With an 8-hour day, a ₹ 800 daily wage and a rate of 2, one hour of overtime is ₹ 200.'),
               ('Can I keep a whole month in one sheet?', 'Yes. Set the days in the period to the number of days in the month (up to 31). For weekly payment, set 7 and save a copy for each week.'),
               ('Does it calculate PF and ESI?', 'No. Most daily-wage site labour is paid gross; if your workers are covered by PF, ESI or welfare board contributions, add those deductions in a separate column or ask for a version through the contact page.')]),

    dict(id='con-material-register-excel', kit='construction', kind='excel', icon='🧱', name='Site Material Inward & Issue Register (Excel)',
         title='Material Register for Construction Site in Excel: Inward, Issue and Stock',
         desc='Free Excel site material register: cement, steel, sand and bricks received with challan and vehicle, issued to gangs by location, balance stock and supplier totals.',
         files=[('Construction-Material-Register.xlsx', 'Site material register')],
         preview={'Construction-Material-Register.xlsx': ('Stock', 'A2:I15')},
         lead='Know what material came to site, who it went to and what is left in the store. Record each delivery with the supplier, challan and vehicle number, and each issue with the gang and the location of work. The Stock sheet keeps the balance of every material, its average purchase rate and value, and flags materials that are below the reorder level; a supplier summary totals deliveries for checking bills.',
         inside=['Materials sheet: material, unit, opening stock, reorder level and standard rate, with common site materials filled in',
                 'Suppliers sheet: name, phone and GSTIN',
                 'Inward register with 1,000 rows: date, material, supplier, challan or bill number, vehicle number, quantity, rate and amount',
                 'Issue register with 1,000 rows: date, material, quantity, issued to (gang or sub-contractor), location of work and issued by',
                 'Stock sheet: opening, received, issued, balance, average rate, value and a Reorder / Short warning; supplier summary with deliveries and value'],
         steps=['On the Materials sheet keep the materials you use and type the opening stock on the day you start the register.',
                'List your suppliers on the Suppliers sheet.',
                'When a vehicle arrives, check the quantity, then add a row on the Inward sheet with the challan number and vehicle number. Write who received it.',
                'Every time material leaves the store, add a row on the Issue sheet: quantity, who took it and for which work and location.',
                'Open the Stock sheet daily: reorder before materials run out. At month end, compare the Supplier summary with the suppliers\' bills.'],
         tips=['Count cement bags and weigh steel on arrival; record the quantity actually received, not the quantity on the challan, and note any shortage.',
               'Compare material issued with the theoretical quantity for the work done (for example cement bags per cum of concrete) every week; a big difference points to wastage or theft.',
               'Do a physical stock count every month and add an issue or inward row with the note "stock adjustment" for any difference.',
               'Keep steel by diameter (8, 10, 12, 16 mm) as separate materials, because they are ordered and used separately.'],
         faqs=[('How is the average rate calculated?', 'It is the total amount of all deliveries divided by the total quantity received. If nothing has been received yet, the standard rate from the Materials sheet is used.'),
               ('What does "Short" mean on the Stock sheet?', 'More has been issued than was received plus the opening stock. Usually an inward entry is missing or a quantity was typed wrongly.'),
               ('Can I use it for two sites?', 'Keep one file per site. Material moved from one site to another is an Issue at the first site and an Inward at the second, with the note "transfer".')]),

    dict(id='con-site-diary-word', kit='construction', kind='word', icon='📔', name='Daily Site Diary / Progress Report (Word)',
         title='Daily Site Diary Format in Word: Construction Daily Progress Report',
         desc='Free Word daily site diary for construction: weather, manpower by trade, machinery, work done with quantities, materials received, instructions, hindrances, safety and plan.',
         files=[('Construction-Daily-Site-Diary.docx', 'Daily site diary (Word)')],
         lead='A one-page daily progress report that records what happened on site today: the weather, the labour and machines on site, the work done with locations and quantities, the material received, instructions from the client or architect, delays and their reasons, safety observations and the plan for tomorrow. Written every day, it is the best evidence when a delay or extra item is disputed months later.',
         inside=['Project, date, day number, weather (morning and afternoon) and working hours',
                 'Manpower table by trade and agency, with total on site', 'Machinery and equipment table with hours worked and idle',
                 'Work done today: activity, location, quantity and unit', 'Materials received and tests done (slump, cube casting)',
                 'Instructions received, visitors, hindrances and delays with hours lost, safety observations, plan for tomorrow and signatures'],
         steps=['Open the file in Word, Google Docs or LibreOffice and type your project name and contractor name at the top. Save it as your master copy.',
                'Each evening, open the master, save it with the date in the name (for example Site-Diary-2026-11-02) and fill in the day\'s details.',
                'Take the manpower numbers from your labour register and the material deliveries from the material register.',
                'Write every instruction from the client, architect or engineer with the name of the person who gave it.',
                'Print, sign and get it countersigned by the client\'s engineer if they are on site; file it day by day.'],
         tips=['Write hindrances the same day with the hours lost (rain, no drawings, power cut, client changes): they are the basis for an extension of time.',
               'Add two or three photos to the file when something important happens, such as reinforcement before a slab pour.',
               'Number the days from the start of work so it is easy to compare with the schedule.'],
         faqs=[('Who should write the site diary?', 'The site engineer or supervisor in charge for the day. The client\'s representative can countersign it to agree the facts.'),
               ('Is a site diary the same as a measurement book?', 'No. The diary records daily events and progress; the measurement book records exact measurements for billing. Use the RA Bill & Measurement Book workbook for that.'),
               ('Can I fill it on a phone?', 'Yes. The .docx file opens in the Word and Google Docs apps on phones, and you can share the day\'s report as PDF.')]),

    dict(id='con-work-order-word', kit='construction', kind='word', icon='📜', name='Work Order & Contract Agreement Draft (Word)',
         title='Work Order Format for Contractors in Word: Agreement Starting Draft',
         desc='Free editable work order and contract agreement draft for building work: scope, schedule of rates, value, timelines, RA billing, retention, safety, delays and variations.',
         files=[('Construction-Work-Order-Draft.docx', 'Work order and agreement draft (Word)')],
         lead='A plain-English starting draft for giving a construction job to a contractor or sub-contractor. It covers what most small contracts leave out and later argue about: the exact scope, who supplies which materials, the schedule of rates, start and completion dates, monthly RA billing and retention, labour and safety duties, delays, variations, defects liability and how disputes are settled. Replace the [bracketed] parts and remove clauses that do not apply.',
         inside=['Work order header: number, date, employer, contractor, site and subject',
                 'Scope of work and the materials list (who supplies what: employer or contractor)', 'Schedule of rates table with item, unit, quantity, rate and amount',
                 'Contract value, start date, completion period, defects liability period and retention',
                 'Payment terms (RA bills on measured work), taxes and deductions, labour law compliance, safety and PPE, quality and testing',
                 'Delays and compensation, variations and extra items, termination, disputes, acceptance and signatures with witnesses'],
         steps=['Open the file in Word, Google Docs or LibreOffice and read it through once.',
                'Replace every [bracketed] item. Use Find (Ctrl + F) and search for "[" to jump from one to the next.',
                'Fill the schedule of rates from your estimate or BOQ, so that both sides agree on the unit and rate of each item before work starts.',
                'Delete clauses that do not apply to your job and add any special conditions under the last heading.',
                'Have the draft checked by your lawyer or adviser, then print two copies, sign both with two witnesses, and give one to the other party.'],
         tips=['Make the materials list very clear: "cement and steel by employer, everything else by contractor" avoids most billing disputes.',
               'Tie each RA bill to measurements in a measurement book signed by both sides; the RA Bill workbook in this toolkit does the calculation.',
               'Stamp duty and registration rules for agreements differ by state; ask your adviser whether the agreement needs stamp paper.',
               'Keep the original drawings and BOQ attached as annexures and number every page.'],
         faqs=[('Is this a legally complete contract?', 'No. It is a starting draft with common, simple clauses to save you typing. Contract law, stamp duty and labour rules differ by state and by type of work, so have the final version checked by a lawyer before signing.'),
               ('What is the difference between a work order and an agreement?', 'A work order is a short instruction to carry out a job at agreed rates; an agreement sets out the full terms both sides sign. This draft combines them, which is common for small and medium jobs.'),
               ('What is the defects liability period?', 'The period after completion (often 6 to 12 months) during which the contractor must repair defects at their own cost. Retention money is usually released after it ends.')]),
]
